export type EventSessionStructuredOutput = {
  type: "session.structured_output"
  properties: {
    sessionID: string
    outcome:
      | {
          status: "accepted"
          attempts: number
          value: unknown
        }
      | {
          status: "failed"
          reason: "exhausted" | "missing" | "step_limit" | "aborted" | "error"
          attempts: number
        }
  }
}

export type EventSessionStructuredOutputRejected = {
  type: "session.structured_output_rejected"
  properties: {
    sessionID: string
    attempt: number
    maxAttempts: number
    errors: Array<{
      path: string
      keyword: string
      message: string
    }>
  }
}
